   344	sub _validate_catalog {
   345	    return if $validated;
   346	
   347	    my %actions;
   348	    my %labels;
   349	    for my $entry (@ENTRIES) {
   350	        ref($entry) eq 'HASH'
   351	            or die "Digital Assets catalog entry must be a hash reference\n";
   352	
   353	        for my $field (qw(category action selector label prompt)) {
   354	            defined($entry->{$field}) && length($entry->{$field})
   355	                or die "Digital Assets catalog entry is missing $field\n";
   356	            $entry->{$field} !~ /[\t\r\n]/
   357	                or die "Digital Assets catalog entry contains an unsafe $field\n";
   358	        }
   359	
   360	        $entry->{category} =~ /\A(?:docx|pdf|image)\z/
   361	            or die "Digital Assets catalog entry has an unsupported category\n";
   362	        $entry->{action} =~ /\A[a-z0-9]+(?:-[a-z0-9]+)*\z/
   363	            or die "Digital Assets catalog entry has an unsafe action\n";
   364	        $entry->{selector} =~ /\A(?:docx|pdf|image|markdown|pdf-list|image-list)\z/
   365	            or die "Digital Assets catalog entry has an unsupported selector\n";
   366	        !$actions{$entry->{action}}++
   367	            or die "Digital Assets catalog contains a duplicate action\n";
   368	        !$labels{"$entry->{category}\0$entry->{label}"}++
   369	            or die "Digital Assets catalog contains a duplicate category label\n";
   370	    }
   371	
   372	    $validated = 1;
   373	    return;
   374	}
