   136	sub run_action {
   137	    my ($self, $action, @arguments) = @_;
   138	
   139	    return $self->server->show_status
   140	        if $action eq 'server-status';
   141	    return $self->server->start
   142	        if $action eq 'start-server';
   143	    return $self->server->repair
   144	        if $action eq 'repair-server';
   145	    return $self->server->stop
   146	        if $action eq 'stop-server';
   147	
   148	    if ($action eq 'reconnect-usb') {
   149	        my $status = $self->device->run_host(15, 'reconnect', 'device');
   150	        print $self->device->capture_devices if $status == 0;
   151	        return $status;
   152	    }
   153	    if ($action eq 'reconnect-offline') {
   154	        my $status = $self->device->run_host(15, 'reconnect', 'offline');
   155	        print $self->device->capture_devices if $status == 0;
   156	        return $status;
   157	    }
   158	    if ($action eq 'wait-any-device') {
   159	        $self->server->ensure_responsive;
   160	        print 'Waiting up to '
   161	            . $self->config->adb_wait_seconds
   162	            . " seconds for an authorized device...\n";
   163	        my $status = $self->command->run_signal(
   164	            'TERM',
   165	            3,
   166	            $self->config->adb_wait_seconds,
   167	            $self->config->require_tool('adb'),
   168	            'wait-for-device',
   169	        );
   170	        if ($status != 0) {
   171	            $self->server->repair if !$self->server->probe;
   172	            fail('timed out waiting for an authorized Android device');
   173	        }
   174	        print $self->device->capture_devices;
   175	        return 0;
   176	    }
   177	    if ($action eq 'list-devices') {
   178	        print $self->device->capture_devices;
   179	        return 0;
   180	    }
   181	    return $self->device->diagnostics
   182	        if $action eq 'diagnose-devices';
   183	    return $self->command->run(
   184	        20,
   185	        $self->config->require_tool('adb'),
   186	        'version',
   187	    ) if $action eq 'adb-version';
   188	    if ($action eq 'host-features') {
   189	        my $features = $self->device->capture_host(20, 'host-features');
   190	        print join("\n", grep { $_ ne q{} } split /,/, $features), "\n";
   191	        return 0;
   192	    }
   193	    return $self->device->run_host(20, 'mdns', 'services')
   194	        if $action eq 'mdns-services';
   195	    return $self->device->run_host(20, 'disconnect')
   196	        if $action eq 'disconnect-all';
   197	    return $self->device->run_host(60, 'pair', @arguments)
   198	        if $action eq 'pair-wireless';
   199	    return $self->device->run_host(30, 'connect', @arguments)
   200	        if $action eq 'connect-wireless';
   201	    return $self->device->run_host(20, 'disconnect', @arguments)
   202	        if $action eq 'disconnect-wireless';
   203	
   204	    return $self->device->device_summary($arguments[0])
   205	        if $action eq 'device-summary';
   206	    if ($action eq 'interactive-shell') {
   207	        $self->device->wait_for_serial($arguments[0]);
   208	        return $self->command->run_unbounded(
   209	            $self->config->require_tool('adb'),
   210	            '-s',
   211	            $arguments[0],
   212	            'shell',
   213	        );
   214	    }
   215	    return $self->package->list_user_packages($arguments[0])
   216	        if $action eq 'list-packages';
   217	    return $self->package->current_activity($arguments[0])
   218	        if $action eq 'current-activity';
   219	    return $self->device->run_serial(
   220	        $self->config->adb_command_seconds,
   221	        $arguments[0],
   222	        'shell',
   223	        'dumpsys',
   224	        'battery',
   225	    ) if $action eq 'battery-status';
   226	    return $self->device->run_serial(
   227	        $self->config->adb_command_seconds,
   228	        $arguments[0],
   229	        'shell',
   230	        'df',
   231	        '-h',
   232	    ) if $action eq 'storage-status';
   233	    if ($action eq 'cpu-memory') {
   234	        print "--- CPU ---\n";
   235	        my $status = $self->device->run_serial(
   236	            $self->config->adb_command_seconds,
   237	            $arguments[0],
   238	            'shell',
   239	            'top',
   240	            '-b',
   241	            '-n',
   242	            '1',
   243	            '-m',
   244	            '15',
   245	        );
   246	        return $status if $status != 0;
   247	        print "\n--- Memory ---\n";
   248	        return $self->device->run_serial(
   249	            $self->config->adb_command_seconds,
   250	            $arguments[0],
   251	            'shell',
   252	            'dumpsys',
   253	            'meminfo',
   254	        );
   255	    }
   256	    return $self->device->run_serial(
   257	        $self->config->adb_command_seconds,
   258	        $arguments[0],
   259	        'shell',
   260	        'pm',
   261	        'list',
   262	        'users',
   263	    ) if $action eq 'list-android-users';
   264	
   265	    return $self->transfer->screenshot($arguments[0])
   266	        if $action eq 'screenshot';
   267	    return $self->transfer->screenrecord($arguments[0])
   268	        if $action eq 'screenrecord';
   269	    if ($action eq 'logcat-live') {
   270	        $self->device->wait_for_serial($arguments[0]);
   271	        return $self->command->run_unbounded(
   272	            $self->config->require_tool('adb'),
   273	            '-s',
   274	            $arguments[0],
   275	            'logcat',
   276	        );
   277	    }
   278	    return $self->device->run_serial(
   279	        60,
   280	        $arguments[0],
   281	        'logcat',
   282	        '-d',
   283	        '-t',
   284	        '500',
   285	    ) if $action eq 'logcat-recent';
   286	    return $self->transfer->bugreport($arguments[0])
   287	        if $action eq 'bugreport';
   288	    return $self->backup->backup($arguments[0])
   289	        if $action eq 'backup-device';
   290	
   291	    return $self->package->install($arguments[0], $arguments[1], 0)
   292	        if $action eq 'install-apk';
   293	    return $self->package->install($arguments[0], $arguments[1], 1)
   294	        if $action eq 'install-apk-replace';
   295	    return $self->package->uninstall($arguments[0], $arguments[1])
   296	        if $action eq 'uninstall-package';
   297	    return $self->package->clear_data($arguments[0], $arguments[1])
   298	        if $action eq 'clear-app-data';
   299	    return $self->permissions->grant($arguments[0], $arguments[1], $arguments[2])
   300	        if $action eq 'grant-permission';
   301	    return $self->transfer->pull_path($arguments[0], $arguments[1])
   302	        if $action eq 'pull-path';
   303	    return $self->transfer->push_download($arguments[0], $arguments[1])
   304	        if $action eq 'push-download';
   305	
   306	    if ($action eq 'list-forwards') {
   307	        $self->device->wait_for_serial($arguments[0]);
   308	        my $status = $self->device->run_serial(
   309	            30,
   310	            $arguments[0],
   311	            'forward',
   312	            '--list',
   313	        );
   314	        return $status if $status != 0;
   315	        return $self->device->run_serial(
   316	            30,
   317	            $arguments[0],
   318	            'reverse',
   319	            '--list',
   320	        );
   321	    }
   322	    return $self->device->run_serial(
   323	        $self->config->adb_command_seconds,
   324	        $arguments[0],
   325	        'forward',
   326	        "tcp:$arguments[1]",
   327	        "tcp:$arguments[2]",
   328	    ) if $action eq 'forward-tcp';
   329	    return $self->device->run_serial(
   330	        $self->config->adb_command_seconds,
   331	        $arguments[0],
   332	        'reverse',
   333	        "tcp:$arguments[1]",
   334	        "tcp:$arguments[2]",
   335	    ) if $action eq 'reverse-tcp';
   336	
   337	    if ($action eq 'enable-tcpip-5555') {
   338	        my $status = $self->device->run_serial(
   339	            $self->config->adb_command_seconds,
   340	            $arguments[0],
   341	            'tcpip',
   342	            '5555',
   343	        );
   344	        if ($status == 0) {
   345	            print "TCP/IP debugging is now listening on the device. Treat this as temporary and disable Wireless debugging when finished.\n";
   346	        }
   347	        return $status;
   348	    }
   349	    return $self->device->run_serial(
   350	        $self->config->adb_command_seconds,
   351	        $arguments[0],
   352	        'reboot',
   353	    ) if $action eq 'reboot-system';
   354	    return $self->device->run_serial(
   355	        $self->config->adb_command_seconds,
   356	        $arguments[0],
   357	        'reboot',
   358	        'recovery',
   359	    ) if $action eq 'reboot-recovery';
   360	    return $self->device->run_serial(
   361	        $self->config->adb_command_seconds,
   362	        $arguments[0],
   363	        'reboot',
   364	        'bootloader',
   365	    ) if $action eq 'reboot-bootloader';
   366	    return $self->device->run_serial(
   367	        $self->config->adb_command_seconds,
   368	        $arguments[0],
   369	        'reboot',
   370	        'sideload',
   371	    ) if $action eq 'reboot-sideload';
   372	
   373	    return $self->samsung->download(
   374	        $arguments[0],
   375	        $arguments[1],
   376	        $arguments[2],
   377	    )
   378	        if $action eq 'samsung-download-firmware';
   379	    return $self->samsung->flash($arguments[0], $arguments[1], 'keep-data')
   380	        if $action eq 'samsung-flash-keep-data';
   381	    return $self->samsung->flash($arguments[0], $arguments[1], 'factory-reset')
   382	        if $action eq 'samsung-flash-factory-reset';
   383	
   384	    return $self->google_pixel->list_devices
   385	        if $action eq 'fastboot-list';
   386	    return $self->google_pixel->info($arguments[0])
   387	        if $action eq 'fastboot-info';
   388	    return $self->google_pixel->reboot($arguments[0], 0)
   389	        if $action eq 'fastboot-reboot';
   390	    return $self->google_pixel->reboot($arguments[0], 1)
   391	        if $action eq 'fastboot-reboot-bootloader';
